import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './CSS/Wishlist.css';

function Wishlist({ onSelectProduct }) {
  const [wishlistItems, setWishlistItems] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchWishlist = () => {
      const saved = JSON.parse(localStorage.getItem('wishlistItems')) || [];
      setWishlistItems(saved);
    };

    fetchWishlist();
    window.addEventListener('wishlistUpdated', fetchWishlist);
    window.addEventListener('storage', fetchWishlist);

    return () => {
      window.removeEventListener('wishlistUpdated', fetchWishlist);
      window.removeEventListener('storage', fetchWishlist);
    };
  }, []);

  const handleRemove = (id, e) => {
    e.stopPropagation();
    const updated = wishlistItems.filter(item => (item._id || item.id) !== id);
    setWishlistItems(updated);
    localStorage.setItem('wishlistItems', JSON.stringify(updated));
    window.dispatchEvent(new Event('wishlistUpdated'));
  };

  return (
    <div className="wishlist-container" style={{ padding: '20px' }}>
      <h2>My Wishlist ({wishlistItems.length})</h2>

      {wishlistItems.length === 0 ? (
        <div style={{ textAlign: 'center', marginTop: '50px' }}>
          <p>Your wishlist is empty.</p>
          <button 
            onClick={() => navigate('/products')}
            style={{ padding: '10px 20px', backgroundColor: '#130352', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' }}
          >
            Explore Products
          </button>
        </div>
      ) : (
        <div className="wishlist-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '20px', marginTop: '20px' }}>
          {wishlistItems.map((product) => (
            <div 
              key={product._id || product.id} 
              className="product-card"
              onClick={() => onSelectProduct && onSelectProduct(product)}
              style={{ cursor: 'pointer', border: '1px solid #e2e8f0', borderRadius: '8px', padding: '15px', background: '#fff', position: 'relative' }}
            >
              <img 
                src={product.image || product.images?.[0]} 
                alt={product.title || product.name} 
                style={{ width: '100%', height: '180px', objectFit: 'contain' }} 
              />
              <h4 style={{ fontSize: '14px', margin: '10px 0 5px 0' }}>{product.title || product.name}</h4>
              <p style={{ fontWeight: 'bold', color: '#6366f1' }}>${product.price}</p>
              
              <button 
                onClick={(e) => handleRemove(product._id || product.id, e)}
                style={{
                  marginTop: '10px',
                  width: '100%',
                  backgroundColor: '#ef4444',
                  color: '#fff',
                  border: 'none',
                  padding: '8px',
                  borderRadius: '5px',
                  cursor: 'pointer',
                  fontSize: '13px'
                }}
              >
                Remove from Wishlist
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Wishlist;
